import * as THREE from 'three';import {autoFitOrthographicBounds} from '../camera-fit.js';import {PIANO_PLACEMENT} from './piano-view.js';
export function createHeadphones(){const root=new THREE.Group();root.name='music.worn-headphones';const dark=new THREE.MeshStandardMaterial({color:'#344d57',roughness:.65}),pad=new THREE.MeshStandardMaterial({color:'#d0ab76',roughness:.95});const ellipsoid=(x,y,z,s,material)=>{const mesh=new THREE.Mesh(new THREE.SphereGeometry(1,20,12),material);mesh.position.set(x,y,z);mesh.scale.fromArray(s);mesh.castShadow=true;root.add(mesh);};for(const sign of[-1,1]){ellipsoid(sign*.482,.975,-.105,[.062,.137,.112],dark);ellipsoid(sign*.438,.975,-.105,[.035,.120,.098],pad);}const points=[];for(let i=0;i<=48;i++){const t=i*Math.PI/48;points.push(new THREE.Vector3(Math.cos(t)*.480,.99+Math.sin(t)*.337,-.145));}root.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),64,.022,8,false),dark));return root;}
/** Borrow the original player after the modal lock; never enter ActivitySession. */
export function createMusicSession({zoneRoot,player,model,poser,kind='piano',reduced=false}){
 if(!zoneRoot||!player||!model||!poser)throw Error('MusicPlayerUnavailable');const saved={position:player.position.clone(),quaternion:player.quaternion.clone(),scale:player.scale.clone(),modelPosition:model.position.clone(),modelQuaternion:model.quaternion.clone(),modelScale:model.scale.clone(),pose:poser.getState(),children:player.children.map(n=>[n,n.visible])};let alive=true,pressed=new Set(),last='';const headphones=kind==='listen'?createHeadphones():null,parked=kind==='listen'?zoneRoot.getObjectByName('music.headphones-resting'):null,parkedVisible=parked?.visible;if(parked)parked.visible=false;
 poser.setPose(kind==='piano'?'piano':'sit',1,0);const pose=poser.getState(),seat=kind==='piano'?{x:PIANO_PLACEMENT.x,y:PIANO_PLACEMENT.seatY,z:PIANO_PLACEMENT.seatZ,yaw:Math.PI}:{x:3.35,y:.55,z:1.15,yaw:0};const local=new THREE.Vector3(seat.x,seat.y-pose.seatContactY,seat.z-(Math.cos(seat.yaw)*pose.anchors.seat[2]));zoneRoot.updateWorldMatrix(true,false);const position=zoneRoot.localToWorld(local);if(player.parent)player.parent.worldToLocal(position);player.position.copy(position);const rotation=zoneRoot.getWorldQuaternion(new THREE.Quaternion()).multiply(new THREE.Quaternion().setFromAxisAngle(THREE.Object3D.DEFAULT_UP,seat.yaw));if(player.parent)rotation.premultiply(player.parent.getWorldQuaternion(new THREE.Quaternion()).invert());player.quaternion.copy(rotation);player.scale.set(1,1,1);model.position.set(0,0,0);model.quaternion.identity();model.scale.set(1,1,1);for(const child of player.children)if(child!==model)child.visible=false;if(headphones)model.add(headphones);player.updateWorldMatrix(true,true);
 function update(){if(!alive||kind!=='piano')return;const low=[...pressed].some(n=>n<64),high=[...pressed].some(n=>n>=64),name=reduced?'piano':low&&high?'pianoBoth':low?'pianoRight':high?'pianoLeft':'piano';if(name!==last){poser.setPose(name,1,0);last=name;player.updateWorldMatrix(true,true);}}
 return{setPressed(notes){pressed=new Set(notes);update();},update,get position(){return local.clone();},dispose(){if(!alive)return;alive=false;if(parked)parked.visible=parkedVisible;if(headphones){const geometry=new Set(),materials=new Set();headphones.traverse(o=>{if(o.geometry)geometry.add(o.geometry);if(o.material)materials.add(o.material);});geometry.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());headphones.removeFromParent();}player.position.copy(saved.position);player.quaternion.copy(saved.quaternion);player.scale.copy(saved.scale);model.position.copy(saved.modelPosition);model.quaternion.copy(saved.modelQuaternion);model.scale.copy(saved.modelScale);poser.setPose(saved.pose.name,saved.pose.amount,saved.pose.time);for(const[n,v]of saved.children)n.visible=v;player.updateWorldMatrix(true,true);}};
}
export function fitMusicCamera(camera,zoneRoot,viewport,kind='piano'){zoneRoot.updateWorldMatrix(true,false);const piano=kind==='piano',eye=piano?[3,4.8,-.5]:[6.8,3.9,6.7],target=piano?[-2.55,1.2,-1.4]:[3.7,1.1,1.0];camera.position.copy(zoneRoot.localToWorld(new THREE.Vector3(...eye)));camera.up.set(0,1,0);camera.lookAt(zoneRoot.localToWorld(new THREE.Vector3(...target)));camera.updateMatrixWorld(true);const bounds=new THREE.Box3(new THREE.Vector3(...(piano?[-4.25,.02,-4.65]:[2.5,.02,.4])),new THREE.Vector3(...(piano?[-1.0,3.07,.62]:[5.18,2.06,1.82]))).applyMatrix4(zoneRoot.matrixWorld);autoFitOrthographicBounds({camera,worldBounds:bounds,viewport,paddingPx:{top:6,right:10,bottom:8,left:10}});camera.updateMatrixWorld(true);return bounds;}
